alter table public.vp_accounts add column installer_quiz_version text;
create table public.vp_installer_quiz_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.vp_accounts(user_id),version text not null,score integer not null check(score between 0 and 20),passed boolean not null,created_at timestamptz not null default now());
alter table public.vp_installer_quiz_attempts enable row level security;
revoke all on public.vp_installer_quiz_attempts from public,anon,authenticated;
grant select on public.vp_installer_quiz_attempts to authenticated;
create policy own_installer_attempts on public.vp_installer_quiz_attempts for select to authenticated using(user_id=auth.uid() or public.vp_is_admin());
create index vp_installer_attempts_user_time on public.vp_installer_quiz_attempts(user_id,created_at desc);
insert into vp_private.sales_quiz values ('installer-v1',$quiz$[{"id": 1, "prompt": "Was muss vor Montagebeginn feststehen?", "options": ["Nur die Anzahl der Geräte.", "Leistungsumfang, Objektanforderungen und genaue Gerätevarianten.", "Nur das WLAN-Passwort."], "correct": 1, "critical": false, "explanation": "Auftrag, Planung und Gerätekompatibilität müssen vor Arbeitsbeginn geklärt sein."}, {"id": 2, "prompt": "Wann wird die Funkqualität am Montageort geprüft?", "options": ["Vor der endgültigen Befestigung und danach erneut.", "Nur im Lager.", "Gar nicht bei kleinen Wohnungen."], "correct": 0, "critical": false, "explanation": "Funkbedingungen ändern sich durch Gebäude und Montage. Am tatsächlichen Ort prüfen."}, {"id": 3, "prompt": "Der geplante Montageort hat instabilen Funkempfang. Was tust du?", "options": ["Trotzdem montieren.", "Die Störungsmeldungen ausblenden.", "Standort bzw. Planung ändern und erneut testen."], "correct": 2, "critical": true, "explanation": "Mit instabiler Verbindung keine mangelfreie Funktion bestätigen. Ursache beheben und erneut testen."}, {"id": 4, "prompt": "Wie wird der Magnet eines Öffnungsmelders angeordnet?", "options": ["Beliebig, solange er sichtbar ist.", "Nach Markierung, Ausrichtung und Abstandsvorgaben des konkreten Modells.", "Immer auf dem Boden."], "correct": 1, "critical": false, "explanation": "Magnetseite und Abstand sind modellabhängig; Öffnen und Schließen praktisch prüfen."}, {"id": 5, "prompt": "Was gilt für den endgültigen SmartBracket-Einbau?", "options": ["Nur temporäres Klebeband genügt immer.", "Die Abreißerkennung wird entfernt.", "Geeignete Befestigung nach Anleitung, einschließlich erforderlicher Sabotagefunktion."], "correct": 2, "critical": false, "explanation": "Befestigung und Sabotageerkennung müssen dem Gerätehandbuch entsprechen."}, {"id": 6, "prompt": "Was beeinflusst die Eignung eines PIR-Montageorts?", "options": ["Sichtfeld, Höhe, Wärmequellen, Luftbewegung und Haustiere.", "Nur die Wandfarbe.", "Nur der Abstand zum WLAN-Router."], "correct": 0, "critical": false, "explanation": "PIR-Planung berücksichtigt Erfassungsbereich und Störquellen; keine pauschalen Tierzusagen."}, {"id": 7, "prompt": "Welche Prüfung gehört zu MotionCam?", "options": ["Nur die LED ansehen.", "Erfassung, Fotoübertragung und Bildbereich mit berechtigtem Zugriff prüfen.", "Unbemerkt alle Räume fotografieren."], "correct": 1, "critical": false, "explanation": "Fotoverifizierung erfordert passende Technik und geklärte Bildberechtigungen."}, {"id": 8, "prompt": "Was unterscheidet Jeweller und Wings?", "options": ["Beides ist dasselbe wie WLAN.", "Wings ersetzt alle Melder.", "Jeweller überträgt Ereignisse, Wings bei geeigneten Geräten Fotos."], "correct": 2, "critical": false, "explanation": "Ereignisübertragung und Fotoübertragung müssen bei geeigneten Geräten jeweils funktionieren."}, {"id": 9, "prompt": "Wie prüfst du einen Glasbruchmelder?", "options": ["Mit dem vom Hersteller vorgesehenen Testverfahren und unter passenden Glasbedingungen.", "Durch Zerstören einer Kundenscheibe.", "Nur durch Öffnen des Fensters."], "correct": 0, "critical": false, "explanation": "Keine Scheiben zerstören. Das freigegebene Testverfahren und die Glaseignung beachten."}, {"id": 10, "prompt": "Wie erfolgt der Sirenentest?", "options": ["Ohne Ankündigung mit maximaler Dauer.", "Abgestimmt, kurz und nach Anleitung; Beteiligte und gegebenenfalls Leitstelle informieren.", "Die Sirene dauerhaft deaktivieren."], "correct": 1, "critical": true, "explanation": "Unkoordinierte Tests können Menschen gefährden oder unnötige Einsätze auslösen."}, {"id": 11, "prompt": "Wann ist ein Repeater eine geeignete Lösung?", "options": ["Er behebt jedes Internetproblem.", "Er ersetzt eine beliebige Zentrale.", "Wenn kompatibel und seine Funkstrecken am Objekt geprüft sind."], "correct": 2, "critical": false, "explanation": "Repeater und Hub müssen zusammenpassen; beide Funkstrecken prüfen."}, {"id": 12, "prompt": "Welche Benutzerzugänge sind angemessen?", "options": ["Persönliche Berechtigungen; Kunden behalten Kontrolle, Monteurzugriff nur vereinbart.", "Ein gemeinsames Passwort für alle Kunden.", "Dauerhafter unbemerkter Monteurzugriff."], "correct": 0, "critical": true, "explanation": "Keine gemeinsamen Kundenzugänge oder unvereinbarten Fernzugriffe verwenden."}, {"id": 13, "prompt": "Wie wird der Nachtmodus abgenommen?", "options": ["Ohne Begehung aktivieren.", "Vorgesehene Bereiche und erlaubte Bewegungen mit dem Kunden praktisch testen.", "Alle Melder pauschal deaktivieren."], "correct": 1, "critical": false, "explanation": "Nachtbetrieb muss zum Alltag passen und praktisch verifiziert werden."}, {"id": 14, "prompt": "Was gilt für Brand- und CO-Melder?", "options": ["Jedes Modell erkennt alle Gefahren.", "Sie werden zum Schlafen ausgeschaltet.", "Variante, Einsatzbedingungen und passende Fachplanung bestimmen die Verwendung."], "correct": 2, "critical": false, "explanation": "Rauch, Hitze und CO sind verschiedene Erkennungsarten; genaue Variante beachten."}, {"id": 15, "prompt": "Was prüfst du bei LeaksProtect?", "options": ["Wassererkennung nach Anleitung, Meldung und ggf. separat geplante Absperrung.", "Nur die Gehäusefarbe.", "Automatische Wasserabsperrung ohne Zusatztechnik zusagen."], "correct": 0, "critical": false, "explanation": "Ein Wassermelder ersetzt kein Ventil; eine Absperrung ist eine eigene Funktion."}, {"id": 16, "prompt": "Was tust du, wenn ein Auftrag feste 230-V-Verdrahtung erfordert und dir die Qualifikation fehlt?", "options": ["Mit dem Quiznachweis selbst anschließen.", "Arbeit stoppen und eine geeignete Elektrofachkraft einbeziehen.", "Nur die Kabelfarben vergleichen."], "correct": 1, "critical": true, "explanation": "Die interne Freigabe ersetzt keine Elektrofachqualifikation. Keine Arbeiten außerhalb der eigenen Befähigung."}, {"id": 17, "prompt": "Wann ist der Alarmweg erfolgreich getestet?", "options": ["Wenn die App geöffnet ist.", "Wenn ein einzelner Melder leuchtet.", "Wenn die vereinbarte Kette vom Melder bis zu Sirene und Empfänger geprüft wurde."], "correct": 2, "critical": false, "explanation": "Erkennung, Hubverarbeitung, Signalisierung und Empfang gehören zusammen."}, {"id": 18, "prompt": "Ein Funktionstest schlägt fehl. Was wird dokumentiert?", "options": ["Fehler, betroffene Funktion und weiterer Klärungsbedarf; keine mangelfreie Abnahme.", "Ohne Hinweis als erfolgreich markieren.", "Den Melder unbemerkt deaktivieren."], "correct": 0, "critical": true, "explanation": "Offene Mängel müssen sichtbar bleiben. Nicht verdeckt deaktivieren oder eine erfolgreiche Prüfung erfinden."}, {"id": 19, "prompt": "Was gehört zur Übergabe?", "options": ["Nur eine Rechnung.", "Bedienübung, Alarmplan, Unterlagen, Testergebnisse und offene Punkte.", "Nur der QR-Code des Hubs."], "correct": 1, "critical": false, "explanation": "Der Kunde muss Bedienung und Reaktion verstehen; die dokumentierten Prüfungen gehören dazu."}, {"id": 20, "prompt": "Was bescheinigt dieser Abschlusstest?", "options": ["Eine offizielle Ajax-Herstellerzertifizierung.", "Die Befähigung zu allen Elektroarbeiten.", "Eine interne Wissensprüfung und Portal-Montagefreigabe."], "correct": 2, "critical": false, "explanation": "Der interne Test ist keine Herstellerzertifizierung und kein Ersatz für andere erforderliche Fachqualifikationen."}]$quiz$::jsonb);
create function public.vp_installer_quiz_questions() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform public.vp_require_active();
 return (select jsonb_agg(q-'correct'-'explanation' order by (q->>'id')::int) from vp_private.sales_quiz v cross join lateral jsonb_array_elements(v.questions) q where v.version='installer-v1');
end$$;
create function public.vp_submit_installer_quiz(p_answers jsonb,p_version text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.vp_accounts%rowtype; q jsonb; qs jsonb; score integer:=0; feedback jsonb:='[]'::jsonb; ok boolean; critical_ok boolean:=true; passed_at timestamptz;
begin
 perform public.vp_require_active();
 select * into a from public.vp_accounts where user_id=auth.uid() for update;
 if p_version is distinct from 'installer-v1' then raise exception 'Testversion geändert. Bitte neu laden.';end if;
 if a.installer_approved_at is not null and a.installer_quiz_version=p_version then return jsonb_build_object('passed',true,'alreadyPassed',true,'passedAt',a.installer_approved_at);end if;
 if jsonb_typeof(p_answers) is distinct from 'array' then raise exception 'Bitte alle zwanzig Fragen beantworten.';end if;
 if jsonb_array_length(p_answers)<>20 or exists(select 1 from jsonb_array_elements(p_answers) x where jsonb_typeof(x)<>'number' or x::text not in ('0','1','2')) then raise exception 'Für jede Frage genau eine gültige Antwort wählen.';end if;
 if exists(select 1 from public.vp_installer_quiz_attempts where user_id=a.user_id and created_at>clock_timestamp()-interval '5 seconds') then raise exception 'Bitte fünf Sekunden bis zum nächsten Versuch warten.';end if;
 select questions into qs from vp_private.sales_quiz where version=p_version;
 for q in select value from jsonb_array_elements(qs) loop
  ok=(p_answers->>((q->>'id')::int-1))::int=(q->>'correct')::int;
  if ok then score=score+1;elsif coalesce((q->>'critical')::boolean,false) then critical_ok=false;end if;
  feedback=feedback||jsonb_build_array(jsonb_build_object('id',q->'id','correct',ok,'explanation',q->>'explanation'));
 end loop;
 insert into public.vp_installer_quiz_attempts(user_id,version,score,passed) values(a.user_id,p_version,score,(score>=18 and critical_ok));
 if (score>=18 and critical_ok) then
  passed_at=clock_timestamp();
  update public.vp_accounts set installer_requested_at=coalesce(installer_requested_at,passed_at),installer_approved_at=passed_at,installer_quiz_version=p_version where user_id=a.user_id;
  insert into public.vp_audit(actor,event,target,details) values(a.user_id,'installer_quiz_passed',a.user_id::text,jsonb_build_object('version',p_version,'score',score));
 end if;
 return jsonb_build_object('passed',(score>=18 and critical_ok),'score',score,'total',20,'required',18,'feedback',feedback,'passedAt',passed_at);
end$$;

revoke all on function public.vp_installer_quiz_questions(),public.vp_submit_installer_quiz(jsonb,text) from public,anon,authenticated;
grant execute on function public.vp_installer_quiz_questions(),public.vp_submit_installer_quiz(jsonb,text) to authenticated;
create table public.vp_installation_jobs(id uuid primary key default gen_random_uuid(),installer_id uuid not null references public.vp_accounts(user_id),title text not null,description text not null,location text not null,scheduled_at timestamptz not null,status text not null default 'offered' check(status in ('offered','accepted','cancelled')),created_by uuid not null references public.vp_accounts(user_id),created_at timestamptz not null default now(),accepted_at timestamptz);
alter table public.vp_installation_jobs enable row level security;
revoke all on public.vp_installation_jobs from public,anon,authenticated;
grant select on public.vp_installation_jobs to authenticated;
create policy assigned_jobs on public.vp_installation_jobs for select to authenticated using(public.vp_is_admin() or (installer_id=auth.uid() and public.vp_is_active()));
create index vp_installation_jobs_installer on public.vp_installation_jobs(installer_id,created_at desc);
create function public.vp_offer_installation_job(p_installer uuid,p_title text,p_description text,p_location text,p_scheduled_at timestamptz) returns uuid language plpgsql security definer set search_path='' as $$
declare i uuid;
begin
 perform public.vp_require_admin();
 if not exists(select 1 from public.vp_accounts where user_id=p_installer and status='active' and installer_approved_at is not null and installer_quiz_version='installer-v1') then raise exception 'Monteur muss zuerst die Masterclass bestehen.';end if;
 if length(btrim(coalesce(p_title,''))) not between 5 and 200 or length(btrim(coalesce(p_description,''))) not between 30 and 5000 or length(btrim(coalesce(p_location,''))) not between 3 and 500 or p_scheduled_at is null or p_scheduled_at<=now() then raise exception 'Titel, Leistungsumfang inklusive Vergütung, Ort und künftigen Termin vollständig angeben.';end if;
 insert into public.vp_installation_jobs(installer_id,title,description,location,scheduled_at,created_by) values(p_installer,btrim(p_title),btrim(p_description),btrim(p_location),p_scheduled_at,auth.uid()) returning id into i;
 insert into public.vp_audit(actor,event,target) values(auth.uid(),'installation_offered',i::text);return i;
end$$;
create function public.vp_accept_installation_job(p_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare j public.vp_installation_jobs%rowtype;
begin
 perform public.vp_require_active();
 if not exists(select 1 from public.vp_accounts where user_id=auth.uid() and installer_approved_at is not null and installer_quiz_version='installer-v1') then raise exception 'Masterclass zuerst bestehen.' using errcode='42501';end if;
 select * into j from public.vp_installation_jobs where id=p_id and installer_id=auth.uid() for update;
 if not found then raise exception 'Kein eigener Montageauftrag.' using errcode='42501';end if;
 if j.status='accepted' then return;end if;
 if j.status<>'offered' or j.scheduled_at<=now() then raise exception 'Auftrag ist nicht mehr annehmbar.';end if;
 if exists(select 1 from public.vp_accounts where user_id=auth.uid() and status<>'active') then raise exception 'Partnerzugang gesperrt.';end if;
 update public.vp_installation_jobs set status='accepted',accepted_at=clock_timestamp() where id=p_id;
 insert into public.vp_audit(actor,event,target) values(auth.uid(),'installation_accepted',p_id::text);
end$$;
create function public.vp_cancel_installation_job(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 perform public.vp_require_admin();
 update public.vp_installation_jobs set status='cancelled' where id=p_id;
 if not found then raise exception 'Auftrag nicht gefunden.';end if;
 insert into public.vp_audit(actor,event,target) values(auth.uid(),'installation_cancelled',p_id::text);
end$$;
revoke all on function public.vp_offer_installation_job(uuid,text,text,text,timestamptz),public.vp_accept_installation_job(uuid),public.vp_cancel_installation_job(uuid) from public,anon,authenticated;
grant execute on function public.vp_offer_installation_job(uuid,text,text,text,timestamptz),public.vp_accept_installation_job(uuid),public.vp_cancel_installation_job(uuid) to authenticated;
-- Remove stale onboarding advice about the former manual approval path.
update public.vp_courses set body=replace(body,'Eine bestandene Monteur-Masterclass und die zusätzliche Adminfreigabe sind Voraussetzung für die Monteurrolle.','Die Monteurfreigabe erfolgt nach bestandenem Online-Abschlusstest der Monteurs-Masterclass; erforderliche Fachqualifikationen bleiben Voraussetzung für den jeweiligen Auftrag.') where body like '%Eine bestandene Monteur-Masterclass und die zusätzliche Adminfreigabe sind Voraussetzung für die Monteurrolle.%';
notify pgrst,'reload schema';
